/* Canonical server state is projected into the existing board's local-player view. */
(function(root){'use strict';
const I18N=(typeof ArtifactI18n!=='undefined'?ArtifactI18n:null)||(typeof require==='function'?(function(){try{return require('./i18n.js')}catch(e){return null}})():null);
const T=I18N?I18N.T:(z,e)=>z,pick=I18N?I18N.pick:(o,b)=>o?o[b]:'',cardName=I18N?I18N.cardName:c=>c?c.name:'',cardText=I18N?I18N.cardText:c=>c?c.text||'':'';
const L=I18N?I18N.localize:v=>v;
function project(state,seat){const s=JSON.parse(JSON.stringify(state));if(seat!==1)return s;
 const walk=o=>{if(!o||typeof o!=='object')return;for(const [k,v] of Object.entries(o)){if(k==='owner'&&(v===0||v===1))o[k]=1-v;else if(k==='text'&&typeof v==='string')o[k]=v.replace(/天辉|夜魇/g,x=>x==='天辉'?'夜魇':'天辉');else walk(v);}};walk(s);
 for(const k of ['players','deckSpecs'])if(s[k])s[k].reverse();
 for(const l of s.lanes)for(const k of ['towers','mana','manaBase','improvements'])l[k].reverse();
 for(const k of ['turn','initiative','winner'])if(s[k]===0||s[k]===1)s[k]=1-s[k];return s;
}
root.ArtifactOnlineProjection={project};if(typeof module!=='undefined'){module.exports={project};return;}
const watching=new URLSearchParams(location.search).get('spectate')==='1';
if(watching)document.body.classList.add('spectator');
const net=root.ArtifactOnline,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let snapshot,app,pending=null,queue=[],draining=false,seen=-1,connected=false,inFlight=false,resuming=false;
const game=new ArtifactEngine.Game(ARTIFACT_CARDS);
for(const [method,action,args] of [ ['play','play',(p,handId,targets)=>({handId,targets})],['activate','activate',(p,sourceId,key,targets)=>({sourceId,key,targets})],['pass','pass',()=>({})],['buy','buy',(p,slot)=>({slot})],['hold','hold',()=>({})]])game[method]=(...v)=>{if(watching)throw Error(T('观战模式无法操作对局','Spectators cannot act'));if(pending)throw Error(T('正在提交上一行动','Submitting previous action'));if(!connected)throw Error(T('连接中断，正在重连','Connection lost — reconnecting'));pending={action,args:args(...v)};};
function request(action,args={}){if(watching){app?.onlineError(T('观战模式无法操作对局','Spectators cannot act'));return;}if(inFlight){app?.onlineError(T('上一行动正在确认，请稍候','Previous action is being confirmed'));return;}if(!connected){app?.onlineError(T('连接中断，正在重连；对局已保存','Connection lost — reconnecting; match is saved'));return;}inFlight=true;net.command(action,args).catch(e=>app?.onlineError(e.message)).finally(()=>{inFlight=false;});}
function accept(next){snapshot=next;if(!next.state&&watching){renderWaiting(next);return;}if(!next.state){location.replace('online.html?code='+encodeURIComponent(next.code));return;}if(next.revision<=seen){if(resuming){resuming=false;queue.push({state:project(next.state,next.seat),animate:false});drain();}else app?.onlineStatus();return;}const first=seen<0||resuming;resuming=false;seen=next.revision;queue.push({state:project(next.state,next.seat),animate:!first});drain();}
async function drain(){if(draining||!app)return;draining=true;while(queue.length){while(app.ui.busy)await new Promise(r=>setTimeout(r,40));const next=queue.shift();app.receiveOnline(next.state,next.animate);}draining=false;}
const bridge=root.ArtifactOnlineBridge={game,isSpectator:()=>watching,
 flush(){if(!pending)return false;const cmd=pending;pending=null;app.ui.selection=null;request(cmd.action,cmd.args);return true;},
 deploymentLocked(){return watching||!!snapshot?.deployReady?.[snapshot.seat];},
 mount(a){app=a;net.subscribe(accept);const latest=net.getSnapshot();if(latest){snapshot=latest;if(latest.state&&latest.revision>seen){game.s=project(latest.state,latest.seat);game.s.events=[];seen=latest.revision;}}connected=net.getStatus()==='connected';net.onStatus(status=>{if(status!=='connected')resuming=true;const changed=connected!==(status==='connected');connected=status==='connected';if(changed)app.onlineStatus();});net.onError(e=>app.onlineError(e.message||String(e)));drain();},
 header(){return `<header class="topbar"><a class="wordmark" href="online.html">◈ ${watching?T('实时观战','Live spectating'):T('联机对战','Online battle')}</a><nav><a href="online.html">${T('返回房间','Back to room')}</a><span>${T('匹配码','Match code')} ${esc(snapshot.code)}</span></nav><div class="header-tools"><button class="icon-button" data-action="sound" aria-label="${T('切换声音','Toggle sound')}">♫</button><button class="icon-button" data-action="settings" aria-label="${T('设置','Settings')}">⚙</button><button data-action="log">${T('战斗记录','Battle log')}</button></div></header>`;},
 status(){if(watching)return `<div class="online-battle-status" role="status">${connected?T('实时观战 · 天辉视角','Live spectating · Radiant view'):T('观战连接中断 · 正在重连','Spectator link lost · reconnecting')} · ${game.s.phase==='shop'?T('双方购物中','Both shopping'):game.s.phase==='deploy'?T('双方规划分路中 · 确认前不可见','Both planning lanes · hidden until confirmed'):T('双方手牌保密，可查看棋盘与战斗记录','Hands are hidden; board and battle log are visible')}</div>`;const seat=snapshot.seat,op=snapshot.players[1-seat];let message=net.getStatus()==='replaced'?T('此席位已在另一个页面打开 · 请在新页面继续','This seat is open in another tab · continue there'):!connected?T('连接中断 · 正在自动重连，进度已保存','Connection lost · auto-reconnecting, progress saved'):!op.connected?T('对方暂时离线 · 可等待对方返回','Opponent is offline · you can wait for their return'):T('双方已连接 · 每次行动自动保存','Both connected · every action autosaves');if(game.s.phase==='shop')message+=' · '+(snapshot.shopReady[seat]?T('你已完成购物，等待对方','You finished shopping — waiting for opponent'):T('双方完成购物后进入下一轮','Next round once both finish shopping'));if(game.s.phase==='deploy')message+=' · '+(snapshot.deployReady[seat]?T('已锁定分路，等待对方确认','Lanes locked — waiting for opponent'):T('双方确认前，分路安排互不可见','Lane plans stay hidden until both confirm'));return `<div class="online-battle-status" role="status">${esc(message)}</div>`;},
 endHTML(g){return `<div class="phase-overlay"><section class="end-panel"><div class="eyebrow">MATCH COMPLETE</div><h2>${g.s.winner===2?T('平局','Draw'):watching?(g.s.winner===0?T('天辉胜利','Radiant victory'):T('夜魇胜利','Dire victory')):g.s.winner===0?T('你获得了胜利','You won'):T('本场落败','You lost')}</h2><p>${T('对局结果已保存','Result saved')}</p><div class="lobby-actions"><a class="primary" href="online.html">${T('返回联机大厅','Back to the online lobby')}</a><button class="secondary" data-action="log">${T('查看战斗记录','View battle log')}</button>${!watching?`<button class="secondary" data-action="copy-opponent-deck">${T('保存对手构筑','Save opponent deck')}</button>`:''}</div></section></div>`;},
 action(name,el,ctx){if(watching&&['confirm-surrender','surrender','finish-shop','finish-deploy','reset-deploy','unassign-deploy','assign-deploy','select-deploy','buy','hold','pass','play','activate','equip','use-skill'].includes(name)){ctx.toast(T('正在只读观战','Spectating read-only'));return true;}if(['lobby','start','resume','decks','collection'].includes(name)){location.href='online.html';return true;}if(name==='save-match'){ctx.toast(T('联机对局已由服务器自动保存','Online matches autosave on the server'));return true;}if(name==='confirm-surrender'){document.querySelector('#modal')?.close();request('concede');return true;}if(name==='finish-shop'){if(!snapshot.shopReady[snapshot.seat])request('shopReady');else ctx.toast(T('已完成购物，等待对方','Shopping done — waiting for opponent'));return true;}if(name==='finish-deploy'){if(bridge.deploymentLocked()){ctx.toast(T('已确认分路，等待对方','Lanes confirmed — waiting for opponent'));return true;}const plan=ctx.plan();if(!plan.complete){ctx.toast(T('请安排所有待回归英雄','Assign all returning heroes'));return true;}request('deployReady',{assignments:plan.ready.map(u=>({uid:u.uid,lane:plan.lane(u.uid)}))});return true;}if(['reset-deploy','unassign-deploy','assign-deploy'].includes(name)&&bridge.deploymentLocked()){ctx.toast(T('分路已锁定，等待对方','Lanes locked — waiting for opponent'));return true;}if(['buy','hold'].includes(name)&&snapshot.shopReady[snapshot.seat]){ctx.toast(T('本轮已完成购物','Already finished shopping this round'));return true;}return false;}
};
I18N&&I18N.onChange&&I18N.onChange(()=>{if(watching&&snapshot&&!snapshot.state)renderWaiting(snapshot);});
function renderWaiting(s){document.querySelector('#app').innerHTML=`<main class="boot"><h1>${T('实时观战','Spectating')} · ${esc(s.code)}</h1><p>${T('等待双方选好构筑并准备。观战不占玩家席位。','Waiting for both players to pick decks and ready up. Spectating takes no seat.')}</p><p>${s.players.map((p,i)=>`${i?T('夜魇','Dire'):T('天辉','Radiant')}：${p.ready?T('已准备','Ready'):p.occupied?T('选择构筑中','Choosing deck'):T('等待玩家','Waiting for player')}`).join(' · ')}</p><a href="online.html">${T('返回联机大厅','Back to the online lobby')}</a></main>`;}
(async()=>{try{const code=new URLSearchParams(location.search).get('code')||net.lastCode();if(!code){location.replace('online.html');return;}snapshot=await net.connect(code,{spectate:watching});connected=true;if(watching&&!snapshot.state){renderWaiting(snapshot);await new Promise(resolve=>{const unsubscribe=net.subscribe(next=>{snapshot=next;renderWaiting(next);if(next.state){unsubscribe();resolve();}});});}if(!snapshot.state){location.replace('online.html?code='+encodeURIComponent(code));return;}game.s=project(snapshot.state,snapshot.seat);game.s.events=[];seen=snapshot.revision;for(const src of ['app.js?v=20260913-mk3','board-input.js?v=20260908-layout6','responsive-battle.js?v=20260912-i18n1','touch-cards.js?v=20260912-i18n1'])await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=src;script.onload=resolve;script.onerror=reject;document.body.appendChild(script);});}catch(e){document.querySelector('#app').innerHTML=`<main class="boot"><h1>${T('暂时无法连接对局','Cannot connect to the match right now')}</h1><p>${esc(e.message||T('请检查服务是否启动','Check that the server is running'))}</p><a href="online.html">${T('返回联机大厅重试','Back to the online lobby to retry')}</a></main>`;}})();

})(typeof window!=='undefined'?window:globalThis);
